def flaky_service():
    global call_count
    call_count += 1
    if call_count < 3:
        raise ConnectionResetError("Remote server dropped connection")
    return {"status": "SUCCESS", "records_synced": 42}

result = resilient_operation_with_retry(flaky_service, max_retries=4)
